record.field:
  query {
  getPreseliCategoriesListing(defaultLanguage: "en"){
    edges {
      node {
         id
         code
	label
	category_id
      }
    }
    totalCount
  }
}

query GetPreseliProductsListing {
    getPreseliProductsListing(
        first: 10, 
        defaultLanguage: "en"
        ) {
        totalCount
        edges {
            node {
                id
                psli_ProductName
                psli_ProductCode
                psli_Description
                psli_Colours
                psli_Material
                psli_Size
                psli_Branding
                psli_Height
                psli_Width
                psli_DimensionUnit
                psli_Weight
                psli_WeightUnit
                psli_previewImages
                psli_Images
                psli_Artwork {
                    path
                }
                psli_DataSheet{
                    path
                }
                psli_LeadTime
                psli_EndUserWebsite{
                    path
                }
                psli_Prices{
                    ... on fieldcollection_PreseliPrices{
                        psli_Name
                        psli_Quantity
                        psli_PriceDetails{
                            Type
                            Description
                            Value
                            Unit
                        }
                    }
                }
                psli_catalogueId{
                    ... on object_PreseliCategories{
                    id
                    }
                }
            }
        }
    }
}
